SELECT  
WHERE s.owner_scope IN ('USER','TENANT')

  AND (POSITION(LOWER(#{query.keyword}) IN LOWER(COALESCE(u.user_name,'')||' '||
    COALESCE(s.user_code,'')||' '||COALESCE(e.com_acct_name,'')||' '||s.id::text))>0)

AND s.enterprise_id=#{query.enterpriseId}
AND s.status=#{query.status}
AND s.owner_scope=#{query.ownerScope}
ORDER BY s.create_time DESC NULLS LAST,s.id DESC
